head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf06000";
scwin.result = undefined;
scwin.dmenus = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dmenus ={
        "bmenu":1
        ,"mmenu":6
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldinf06000' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf06000.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_chgid_onchange
 * @description ipt_chgid 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_chgid_onchange = function(e){
    try {
        scwin.changeId();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf06000.ipt_chgid_onchange' }); }
};

/**
 * @method
 * @name ipt_chgid_onkeypress
 * @description ipt_chgid onkeypress 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_chgid_onkeypress = function(e){
    try {
        fn_engNmCheck()  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_engNmCheck — 키 입력 필터(window.event — xf:input allowChar 속성 권장)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf06000.ipt_chgid_onkeypress' }); }
};

/**
 * @method
 * @name ipt_chgid_onpaste
 * @description ipt_chgid onpaste 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_chgid_onpaste = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf06000.ipt_chgid_onpaste' }); }
};

/**
 * @method
 * @name btn_checkUsrId_onclick
 * @description btn_checkUsrId 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_checkUsrId_onclick = async function(e){
    try {
        await scwin.checkUsrId()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf06000.btn_checkUsrId_onclick' }); }
};

/**
 * @method
 * @name ipt_message_onpaste
 * @description 「(6~20자의 영문/숫자 혼용)」 onpaste 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_message_onpaste = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf06000.ipt_message_onpaste' }); }
};

/**
 * @method
 * @name btn_idChk_onclick
 * @description btn_idChk 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_idChk_onclick = async function(e){
    try {
        await scwin.idChk()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf06000.btn_idChk_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnSaveId
 * @description fn Save Id 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSaveId = async function () {
    const sbmOptions = {
        id: "tx_fnSaveId",
        method: "post",
        action: "/account/userPw.do",
        ref: "dma_fnSaveIdReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_checkUsrId
 * @description check Usr Id 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_checkUsrId = async function () {
    const sbmOptions = {
        id: "tx_fn_checkUsrId",
        method: "post",
        action: "/corp/register.do?method=searchUsrId",
        ref: "dma_checkUsrIdReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name changeId
 * @description change Id 처리
 * @returns {void}
 * @hidden N
 */
scwin.changeId = function () {
    const oldIdVal = $c.util.getComponent('dma_fnSaveIdReq').get('usrId').replace(/ /gi, "");
    if (oldIdVal !== "") {
        $c.util.getComponent('ipt_message').setValue("");
        $("input[name='newYn']").val("");
    }
    return true;
};

/**
 * @method
 * @name idChk
 * @description id Chk 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.idChk = async function () {
    if ($c.str.getByteLength($c.util.getComponent('ipt_nowid').getValue()) === 0) {
        await $c.win.alert("현재 아이디를 입력하세요");
        $c.util.getComponent("ipt_nowid").focus();
    } else {
        if ($c.str.getByteLength($c.util.getComponent('ipt_chgid').getValue()) === 0) {
            await $c.win.alert("변경 아이디를 입력하세요");
            $c.util.getComponent("ipt_chgid").focus();
        } else {
            if ($c.str.getByteLength($c.util.getComponent('dma_fnSaveIdReq').get('newYn')) === 0 || $c.util.getComponent('dma_fnSaveIdReq').get('newYn') === 'N') {
                await $c.win.alert("아이디 중복확인 여부를 확인하십시오.");
                $c.util.getComponent("ipt_chgid").focus();
            } else {
                if (await $c.win.confirm("변경하시겠습니까?")) {
                    scwin.fnNowIdCheck();
                    await scwin.fnSaveId();
                }
            }
        }
    }
};

/**
 * @method
 * @name fnNowIdCheck
 * @description fn Now Id Check 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnNowIdCheck = function () {
    const base_url = "";
    let action_path = "";
    action_path = "/account/userId.do";
    $("input[name='method']").val("checkNowId");
    $.ajax({ type: "POST", async: false, url: base_url + action_path, data: $("#SendForm").serialize(), success: function(data) {
                scwin.result = (typeof data === "string" ? (typeof data === "string" ? JSON.parse(data) : data) : data);
                $c.util.getComponent('ipt_temp').setValue(scwin.result.sendResult);
            }, error: async function(request, status, error) {
                await $c.win.alert("현재 아이디를 조회 할 수 없습니다. 관리자에게 문의하십시오.");
                return;
            }, complete: function() {

            } });
};

/**
 * @method
 * @name fnSaveId
 * @description fn Save Id 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSaveId = async function () {
    if ($c.util.getComponent('ipt_temp').getValue() === '-1') {
        await $c.win.alert("현재 아이디가 일치하지 않습니다.");
        return;
    } else {
        if ($c.util.getComponent('ipt_temp').getValue() === 'R') {
            await $c.win.alert("현재 신청 중인 건이 존재합니다.\n신청중인 건이 존재할 경우 ID변경이 불가합니다.");
            return;
        } else {
            $c.util.getComponent('dma_fnSaveIdReq').set('method', "updateIntegUsrId");
            await scwin.tx_fnSaveId();
        }
    }
};

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name checkUsrIdDone
 * @description check Usr Id Done 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.checkUsrIdDone = function (data) {
    const result = (typeof data === "string" ? JSON.parse(data) : data);
    $c.util.getComponent('ipt_message').setValue(result.message);
    $("input[name='newYn']").val(result.newYn);
    $("input[name='old_integ_usr_id']").val(SendForm.integ_usr_id.value);
    $c.util.getComponent("ipt_message").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
};

/**
 * @method
 * @name checkUsrId
 * @description check Usr Id 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkUsrId = async function () {
    const r = await scwin.tx_fn_checkUsrId();
    try {
        scwin.checkUsrIdDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldinf06000.fn_checkUsrId' });
    }
    return r;
};
